# Downloads 40 free photos (1920 px wide) from Wikimedia Commons into folders per car.
$ErrorActionPreference = "Stop"
Set-Location $PSScriptRoot
$ua = "KifaruDemo/1.0 (car hire demo; photo download script)"
New-Item -ItemType Directory -Force -Path "toyota-hilux-double-cab" | Out-Null
